import pathlib,re,zlib,struct,hashlib,json,datetime
out=pathlib.Path('outputs/6057-aarch64-first-frame-06bf2d320');raw=(out/'display.ppm').read_bytes();match=re.match(rb'P6\s+(\d+)\s+(\d+)\s+255(?:\r\n|[\t\n\r ])',raw);assert match
w,h=map(int,match.groups());pixels=raw[match.end():];assert w>0 and h>0 and len(pixels)==w*h*3
chunk=lambda tag,data:struct.pack('>I',len(data))+tag+data+struct.pack('>I',zlib.crc32(tag+data)&0xffffffff)
scan=b''.join(b'\0'+pixels[y*w*3:(y+1)*w*3]for y in range(h));png=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(scan,9))+chunk(b'IEND',b'');(out/'display.png').write_bytes(png)
p=out/'receipt.json';before=p.read_bytes();(out/'capture-receipt-before-png-recovery.json').write_bytes(before);r=json.loads(before);r['png']={'sha256':hashlib.sha256(png).hexdigest(),'size':[w,h],'rgb_sha256':hashlib.sha256(pixels).hexdigest(),'ppm_sha256':hashlib.sha256(raw).hexdigest(),'nonuniform':len(set(zip(pixels[0::3],pixels[1::3],pixels[2::3])))>1,'conversion':'Lossless RGB P6 to PNG, standard-library zlib; no scaling, recoloring or editing.'};r['conversion_recovery']={'reason':'Pillow not installed; original probe exited1 only after successful QMP capture and serial records. Same captured PPM converted without re-boot.','original_receipt_sha256':hashlib.sha256(before).hexdigest(),'observed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()};p.write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r['png'],indent=2))
